_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>

constexpr int TILE_D = 8;
constexpr int TILE_H = 8;
constexpr int TILE_W = 16;
constexpr int W_BLOCK = 2;
constexpr int THREADS_W = TILE_W / W_BLOCK;
constexpr int TILE_VOLUME = TILE_D * TILE_H * THREADS_W;
constexpr int COUT_TILE = 8;
__global__ void conv3d_forward_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int C_in, int D_in, int H_in, int W_in,
    int C_out, int D_out, int H_out, int W_out,
    int kD, int kH, int kW,
    int stride, int pad, int dilation, int groups,
    bool has_bias)
{
    extern __shared__ float shared_mem[];
    const int shD = (TILE_D - 1) * stride + (kD - 1) * dilation + 1;
    const int shH = (TILE_H - 1) * stride + (kH - 1) * dilation + 1;
    const int shW = (TILE_W - 1) * stride + (kW - 1) * dilation + 1;
    const int input_tile_volume = shD * shH * shW;
    const int kernel_volume = kD * kH * kW;
    float* sh_input = shared_mem;
    float* sh_weight = shared_mem + input_tile_volume;
    const int c_in_per_group = C_in / groups;
    const int c_out_per_group = C_out / groups;
    const int cout_tiles_per_group = (c_out_per_group + COUT_TILE - 1) / COUT_TILE;
    const int g = blockIdx.y / cout_tiles_per_group;
    const int cout_tile = blockIdx.y - g * cout_tiles_per_group;
    const int c_out0 = g * c_out_per_group + cout_tile * COUT_TILE;
    int c_out_count = c_out_per_group - cout_tile * COUT_TILE;
    if (c_out_count > COUT_TILE) c_out_count = COUT_TILE;
    const int n = blockIdx.z;
    const int w_tiles = (W_out + TILE_W - 1) / TILE_W;
    const int h_tiles = (H_out + TILE_H - 1) / TILE_H;
    const int tile_w = blockIdx.x % w_tiles;
    const int tile_h = (blockIdx.x / w_tiles) % h_tiles;
    const int tile_d = blockIdx.x / (w_tiles * h_tiles);
    const int d_out0 = tile_d * TILE_D;
    const int h_out0 = tile_h * TILE_H;
    const int w_out0 = tile_w * TILE_W;
    const int base_d = d_out0 * stride - pad;
    const int base_h = h_out0 * stride - pad;
    const int base_w = w_out0 * stride - pad;
    const int tid = threadIdx.x;
    const int td = tid / (TILE_H * THREADS_W);
    const int th = (tid / THREADS_W) % TILE_H;
    const int tw = tid % THREADS_W;
    const int d_out = d_out0 + td;
    const int h_out = h_out0 + th;
    const int w_out_base = w_out0 + tw;
    const bool valid_output = (d_out < D_out) && (h_out < H_out) && (w_out_base < W_out);
    float sums[W_BLOCK][COUT_TILE];
    #pragma unroll
    for (int wb = 0; wb < W_BLOCK; ++wb) {
        #pragma unroll
        for (int co = 0; co < COUT_TILE; ++co) {
            sums[wb][co] = (has_bias && co < c_out_count) ? bias[c_out0 + co] : 0.0f;
        }
    }
    for (int c = 0; c < c_in_per_group; ++c) {
        const int c_in = g * c_in_per_group + c;
        for (int idx = tid; idx < input_tile_volume; idx += TILE_VOLUME) {
            const int sw = idx % shW;
            const int sh = (idx / shW) % shH;
            const int sd = idx / (shW * shH);
            const int d_in = base_d + sd;
            const int h_in = base_h + sh;
            const int w_in = base_w + sw;
            float value = 0.0f;
            if (d_in >= 0 && d_in < D_in &&
                h_in >= 0 && h_in < H_in &&
                w_in >= 0 && w_in < W_in) {
                const long long in_idx = ((((long long)n * C_in + c_in) * D_in + d_in) * H_in + h_in) * W_in + w_in;
                value = input[in_idx];
            }
            sh_input[idx] = value;
        }
        for (int idx = tid; idx < COUT_TILE * kernel_volume; idx += TILE_VOLUME) {
            const int co = idx / kernel_volume;
            const int wk = idx - co * kernel_volume;
            if (co < c_out_count) {
                const long long w_idx = (((long long)(c_out0 + co) * c_in_per_group + c) * kernel_volume) + wk;
                sh_weight[idx] = weight[w_idx];
            } else {
                sh_weight[idx] = 0.0f;
            }
        }
        __syncthreads();
        if (valid_output) {
            for (int kd = 0; kd < kD; ++kd) {
                const int sd = td * stride + kd * dilation;
                for (int kh = 0; kh < kH; ++kh) {
                    const int sh = th * stride + kh * dilation;
                    const int sh_row = sd * shH + sh;
                    for (int kw = 0; kw < kW; ++kw) {
                        float in_vals[W_BLOCK];
                        #pragma unroll
                        for (int wb = 0; wb < W_BLOCK; ++wb) {
                            const int sw = (tw + wb * THREADS_W) * stride + kw * dilation;
                            in_vals[wb] = sh_input[sh_row * shW + sw];
                        }
                        const int weight_offset = (kd * kH + kh) * kW + kw;
                        #pragma unroll
                        for (int co = 0; co < COUT_TILE; ++co) {
                            const float w_val = sh_weight[co * kernel_volume + weight_offset];
                            #pragma unroll
                            for (int wb = 0; wb < W_BLOCK; ++wb) {
                                sums[wb][co] += in_vals[wb] * w_val;
                            }
                        }
                    }
                }
            }
        }
        __syncthreads();
    }
    if (valid_output) {
        #pragma unroll
        for (int wb = 0; wb < W_BLOCK; ++wb) {
            const int w_out = w_out_base + wb * THREADS_W;
            if (w_out < W_out) {
                #pragma unroll
                for (int co = 0; co < COUT_TILE; ++co) {
                    if (co < c_out_count) {
                        const int c_out = c_out0 + co;
                        const long long out_idx = ((((long long)n * C_out + c_out) * D_out + d_out) * H_out + h_out) * W_out + w_out;
                        output[out_idx] = sums[wb][co];
                    }
                }
            }
        }
    }
}
torch::Tensor conv3d_forward(torch::Tensor input, torch::Tensor weight, torch::Tensor bias,
                             int64_t stride, int64_t padding, int64_t dilation, int64_t groups)
{
    auto x = input.contiguous();
    auto w = weight.contiguous();
    TORCH_CHECK(x.dim() == 5, "input must be 5D (N, C, D, H, W)");
    TORCH_CHECK(w.dim() == 5, "weight must be 5D (C_out, C_in/groups, kD, kH, kW)");
    TORCH_CHECK(x.is_cuda() && w.is_cuda(), "input and weight must be CUDA tensors");
    TORCH_CHECK(x.scalar_type() == at::kFloat && w.scalar_type() == at::kFloat,
                "input and weight must be float32");
    TORCH_CHECK(groups > 0, "groups must be positive");
    TORCH_CHECK(stride > 0 && dilation > 0, "stride and dilation must be positive");
    int N     = (int)x.size(0);
    int C_in  = (int)x.size(1);
    int D_in  = (int)x.size(2);
    int H_in  = (int)x.size(3);
    int W_in  = (int)x.size(4);
    int C_out = (int)w.size(0);
    int kD    = (int)w.size(2);
    int kH    = (int)w.size(3);
    int kW    = (int)w.size(4);
    TORCH_CHECK(C_in % groups == 0, "input channels must be divisible by groups");
    TORCH_CHECK(C_out % groups == 0, "output channels must be divisible by groups");
    TORCH_CHECK(w.size(1) == C_in / groups, "weight input channels do not match input/groups");
    int D_out = (int)((D_in + 2 * padding - dilation * (kD - 1) - 1) / stride + 1);
    int H_out = (int)((H_in + 2 * padding - dilation * (kH - 1) - 1) / stride + 1);
    int W_out = (int)((W_in + 2 * padding - dilation * (kW - 1) - 1) / stride + 1);
    auto out = torch::empty({N, C_out, D_out, H_out, W_out}, x.options());
    long long total = (long long)N * C_out * D_out * H_out * W_out;
    if (total == 0) return out;
    bool has_bias = bias.defined() && bias.numel() > 0;
    auto b = has_bias ? bias.contiguous() : torch::Tensor();
    const float* bias_ptr = has_bias ? b.data_ptr<float>() : nullptr;
    const int shD = (TILE_D - 1) * (int)stride + (kD - 1) * (int)dilation + 1;
    const int shH = (TILE_H - 1) * (int)stride + (kH - 1) * (int)dilation + 1;
    const int shW = (TILE_W - 1) * (int)stride + (kW - 1) * (int)dilation + 1;
    const size_t shared_bytes =
        ((size_t)shD * shH * shW + (size_t)COUT_TILE * kD * kH * kW) * sizeof(float);
    static int max_shared_bytes = -1;
    if (max_shared_bytes < 0) {
        int device = 0;
        cudaGetDevice(&device);
        cudaDeviceGetAttribute(&max_shared_bytes, cudaDevAttrMaxSharedMemoryPerBlockOptin, device);
        cudaError_t attr_status = cudaFuncSetAttribute(
            conv3d_forward_kernel,
            cudaFuncAttributeMaxDynamicSharedMemorySize,
            max_shared_bytes);
        TORCH_CHECK(attr_status == cudaSuccess, cudaGetErrorString(attr_status));
    }
    TORCH_CHECK(shared_bytes <= (size_t)max_shared_bytes,
                "convolution tile requires too much shared memory");
    const int c_out_per_group = C_out / (int)groups;
    const int cout_tiles_per_group = (c_out_per_group + COUT_TILE - 1) / COUT_TILE;
    const long long w_tiles = (W_out + TILE_W - 1) / TILE_W;
    const long long h_tiles = (H_out + TILE_H - 1) / TILE_H;
    const long long d_tiles = (D_out + TILE_D - 1) / TILE_D;
    const long long spatial_tiles = w_tiles * h_tiles * d_tiles;
    dim3 grid(
        (unsigned int)spatial_tiles,
        (unsigned int)(groups * cout_tiles_per_group),
        (unsigned int)N);
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    conv3d_forward_kernel<<<grid, TILE_VOLUME, shared_bytes, stream>>>(
        x.data_ptr<float>(),
        w.data_ptr<float>(),
        bias_ptr,
        out.data_ptr<float>(),
        N, C_in, D_in, H_in, W_in,
        C_out, D_out, H_out, W_out,
        kD, kH, kW,
        (int)stride, (int)padding, (int)dilation, (int)groups,
        has_bias);
    return out;
}
